<?php
/** TEMP PS S1612 run e5b part2 (darbalaukis v3.11 b64 dalis 2/4) */
add_action('init', function(){
  if (!isset($_GET['ps_e5b'])) return;
  $o=array('v'=>'run e5b part2'); global $wpdb; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$wpdb->prefix}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
  $c='';
  $o['part2']=file_put_contents($bk.'/dl-v311.part2',$c); $o['md5']=md5($c); $o['len']=strlen($c);
  header('Content-Type: application/json'); echo json_encode($o); exit;
},99);
